#!/bin/bash
# Pre-commit guard: block if working tree has untracked/unstaged files (DETERMINISTIC).
# Auto-passes when tree is clean. Bypass reason adversarially reviewed.
# Called from .hooks/pre-commit (generated by init-devshop.sh, invoked by husky).
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

DIRTY=$(git status --porcelain 2>/dev/null | grep -E '^\?\?|^ [MD]' || true)
[ -z "$DIRTY" ] && exit 0

# Check for bypass reason
BYPASS=$(git config --get devshop.dirtyTreeReason 2>/dev/null || true)
if [ -n "$BYPASS" ]; then
  # Reason provided — run adversarial review
  echo "⏳ Dirty tree: reviewing reason with adversarial agent..."
  REVIEW_RESULT=$(bash "$SCRIPT_DIR/adversarial-doc-review.sh" dirtyTreeReason "$BYPASS" 2>&1) || {
    echo ""
    echo "✖ ADVERSARIAL REVIEW REJECTED your dirty tree reason."
    echo "  $REVIEW_RESULT"
    echo ""
    echo "  Address the finding above, then update your reason and retry."
    exit 1
  }
  echo "✓ Dirty tree: adversarial review accepted."
  exit 0
fi

echo ""
echo "✖ Working tree not clean before commit. Untracked or unstaged files:"
echo "$DIRTY" | sed 's/^/    /'
echo ""
echo "  Address these before committing — stage, gitignore, or stash."
echo "  If intentionally committing a subset, explain why with:"
echo "    git -c devshop.dirtyTreeReason=\"<why it's OK>\" commit ..."
echo ""
echo "  Your reason will be verified by an independent reviewer."
exit 1
